        render.innerHTML = '<p class="tc-empty">（未捕获到思维链内容：请检查正则捕获组是否正确传入）</p>';
      } else {
        try { render.innerHTML = md(raw); } catch (e) { render.textContent = raw; }
      }
    }
    var rawEl = root.querySelector('.tc-raw');
    if (rawEl) { rawEl.textContent = raw; }

    var head = root.querySelector('.tc-head');
    if (head) {
      head.addEventListener('click', function () {
        setOpen(root, root.getAttribute('data-tc-open') !== '1', false);
      });
    }
    var btns = root.querySelectorAll('.tc-mode');
    for (var i = 0; i < btns.length; i++) {
      btns[i].addEventListener('click', function (ev) {
        try { ev.stopPropagation(); } catch (e) { }
        setMode(root, this.getAttribute('data-tc-mode'));
      });
    }

    setMode(root, 'render');
    setOpen(root, storeGet(OPEN_KEY) === '1', true);
  }

  function bootAll() {
    var wraps = document.querySelectorAll('.tc-wrap');
    for (var i = 0; i < wraps.length; i++) {
      var w = wraps[i];
      if (w.getAttribute('data-tc-ready') === '1') { continue; }
      w.setAttribute('data-tc-ready', '1');
      try { boot(w); } catch (e) { if (window.console && console.warn) { console.warn('[think-chain]', e); } }
    }
    fitHeight();
  }

  bootAll();
  if (document.readyState === 'loading') { document.addEventListener('DOMContentLoaded', bootAll); }
  window.addEventListener('load', fitHeight);
  window.setTimeout(bootAll, 450);
  if (window.ResizeObserver) {
    try {
      var ro = new ResizeObserver(function () { fitHeight(); });
      if (document.body) { ro.observe(document.body); }
    } catch (e) { }
  }
})();
</script>

