      return;
    }
    const current = host.fetch;
    let native = (current[HOOK_MARK] && current[HOOK_MARK].native) || current;
    if (native[OLD_HOOK_MARK] && native[OLD_HOOK_MARK].native) native = native[OLD_HOOK_MARK].native;
